  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["SW4", "SW1", "Module2A"],
      "pins": ["SW4.2", "SW1.2"],
      "nets": ["NET0115", "Boot Select", "EEPROM Write Protect"],
      "observed": "On the CM4 sheet, the Boot Select switch (SW4) pin 2 and the EEPROM Write Protect switch (SW1) pin 2 are both connected to the same net label NET0115.",
      "expected": "Boot-select and EEPROM-write-protect are separate CM4 functions and should be on separate switch nets; pulling one switch low should not affect the other signal.",
      "evidence": [
        {"source": "schematic", "quote": "CM4 sheet: SW4 'Boot Select. Select USB boot if low.' pin 2 label NET0115; SW1 'EEPROM Write Protect' pin 2 label NET0115."},
        {"source": "spec", "quote": "The specification describes separate CM4 interfaces and does not document Boot Select and EEPROM Write Protect being intentionally merged."}
      ],
      "impact": "Operating the Boot Select switch would also assert EEPROM Write Protect, and operating the EEPROM Write Protect switch would also affect boot selection, potentially preventing EEPROM updates or forcing an unintended boot mode.",
      "confidence": 0.65
    },
    {
      "category": "wrong_value",
      "components": ["R56", "U39"],
      "pins": ["U39.FB"],
      "nets": ["+12V", "FB"],
      "observed": "The +12 V DC-DC converter feedback divider uses R56 = 205k from the +12 V output to FB and R29 = 1.8k from FB to ground.",
      "expected": "For a 12 V output, the top feedback resistor should be roughly 10-20 times the bottom resistor (e.g. about 16-20 k for common 1.2 V references), not 205 k; 205 k would imply an output far above 12 V.",
      "evidence": [
        {"source": "schematic", "quote": "Power sheet: U39 output +12V; feedback network labeled R29 1.8k and R56 205k."},
        {"source": "spec", "quote": "Power distribution: DC-DC conversion ... The +12 V rail is part of the intended power architecture."}
      ],
      "impact": "The +12 V rail would be set far too high or fail to regulate correctly, likely causing overvoltage stress, shutdown, or damage to downstream circuitry.",
      "confidence": 0.55
    },
    {
      "category": "short_to_ground",
      "components": ["U38"],
      "pins": ["U38.3"],
      "nets": ["GND", "USB power path"],
      "observed": "The LTC4412 ideal-diode controller U38 has its CTL pin tied to GND.",
      "expected": "For the LTC4412 to enable the ideal-diode USB power path, CTL should be driven high (typically tied to VIN/+5V); tying CTL low disables the controller.",
      "evidence": [
        {"source": "schematic", "quote": "USB sheet: U38 LTC4412xS6 pin 3 CTL connected to GND."},
        {"source": "spec", "quote": "USB input \"OR-ing\"/protection circuitry (LTC4412 ideal-diode controller, U6)."}
      ],
      "impact": "The USB power path is disabled, so USB input cannot be OR-ed onto the board power rail; the board may not operate from USB and the intended ideal-diode power-path behavior is defeated.",
      "confidence": 0.5
    }
  ],
  "summary": "The schematic shows at least one clear net bridge between the CM4 Boot Select and EEPROM Write Protect switch nodes, and also contains suspicious deviations in the +12 V feedback divider and the LTC4412 USB power-path enable connection."
}

